      electrical:`<polyline points="20,168 62,168 76,92 102,218 130,132 151,168 188,168 203,69 230,225 255,126 276,168 382,168" fill="none" stroke="${accent}" stroke-width="4"/><g fill="none" stroke="#fff" opacity=".55"><rect x="42" y="50" width="92" height="52"/><rect x="162" y="50" width="92" height="52"/><rect x="282" y="50" width="92" height="52"/></g>`,
      seismic:`<g stroke="${accent}" fill="none"><path d="M15 178h48l15-18 17 35 22-70 27 91 22-43 19 5h220" stroke-width="4"/><path d="M30 70h340M30 105h340M30 140h340M30 210h340" opacity=".22"/></g><path d="M75 52l42 170M278 52l-35 170" stroke="#fff" opacity=".45"/>`,
      satellite:`<path d="M41 210C96 151 142 174 181 112s87-72 171-78" fill="none" stroke="${accent}" stroke-width="7"/><circle cx="54" cy="200" r="15" fill="none" stroke="#fff"/><circle cx="340" cy="44" r="11" fill="${accent}"/><path d="M20 66h360M20 104h360M20 142h360M20 180h360" stroke="#fff" opacity=".12"/>`,
      hydrology:`<path d="M23 76c73 5 69 83 136 82s68-78 128-65 49 79 94 82" fill="none" stroke="${accent}" stroke-width="10"/><path d="M82 45v185M207 45v185M326 45v185" stroke="#fff" opacity=".25" stroke-dasharray="5 8"/><circle cx="207" cy="158" r="28" fill="none" stroke="#fff"/>`,
      archaeology:`<g fill="none" stroke="${accent}"><path d="M84 218V72h232v146z" stroke-width="3"/><path d="M120 185l31-76 45 63 44-86 48 99"/><circle cx="200" cy="145" r="46"/><path d="M200 99v92M154 145h92"/></g><rect x="262" y="119" width="42" height="55" fill="#071019" stroke="#e66f65" stroke-dasharray="6 5"/>`,
      laboratory:`<g fill="none" stroke="${accent}"><path d="M15 177c32 0 37-96 70-96s31 144 67 144 32-174 73-174 34 126 68 126 31-75 91-75" stroke-width="4"/><circle cx="225" cy="51" r="20"/><circle cx="152" cy="225" r="16"/></g><path d="M28 52h344M28 102h344M28 152h344M28 202h344" stroke="#fff" opacity=".12"/>`,
